// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;

    function setUp() public { c = new Proxy(); }

    // fuzz parameter controls whether the callee should revert (true -> callee reverts)
    function testFuzz_property(bool calleeShouldRevert) public {
        // Deploy a helper callee that can be instructed to revert or succeed.
        CalleeHelper helper = new CalleeHelper(calleeShouldRevert);

        // Call c.forward and observe whether it returns or reverts.
        bool ok;
        try c.forward(address(helper), "0x") {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE: The reference contract forwards and succeeds exactly when the low-level call to callee succeeds.
        // Our helper's behavior: if calleeShouldRevert == true then the low-level call fails (so c.forward should revert => ok == false),
        // otherwise the low-level call succeeds (so c.forward should succeed => ok == true).
        // This holds for the reference implementation for ALL inputs; the mutant inverts the require and thus will fail
        // for the case when the callee succeeds (calleeShouldRevert == false).
        if (calleeShouldRevert) {
            // callee reverts -> forward should revert
            assertTrue(!ok);
        } else {
            // callee succeeds -> forward should succeed
            assertTrue(ok);
        }
    }
}

// Helper that either reverts on any call or simply accepts it.
contract CalleeHelper {
    bool public shouldRevert;
    constructor(bool _shouldRevert) payable {
        shouldRevert = _shouldRevert;
    }

    // Fallback handles the low-level call from C.forward
    fallback() external payable {
        if (shouldRevert) {
            revert("callee revert");
        }
        // otherwise do nothing (succeed)
    }

    receive() external payable {
        if (shouldRevert) {
            revert("callee revert");
        }
    }
}
